      {"name": "Premium", "price": "Not publicly listed (per user/year, monthly or yearly billing)", "billing": "Monthly or yearly per user, 7-day free trial, 30-day money-back guarantee", "features": ["All Starter features", "Cloud call recording", "File enhancement for existing audio recordings", "Voice effects (pitch shift, reverb, robotic voice)", "Team license management"]},
      {"name": "Elite (Coming Soon)", "price": "$228 USD/user/year (pre-signup discount advertised)", "billing": "Annual per user; pre-launch signup pricing", "features": ["All Premium features", "Meeting transcription", "Performance analysis", "Risk analysis and improvement suggestions"]},
