                    {"name": "Growth", "price": "Custom pricing", "billing": "Annual contract; contact sales for a quote", "features": ["180 AI writing assistant drafts per year", "2,500 AI search credits, 25,000 pages analyzed, 5,000 tracked keywords, 25 tracked competitors", "500,000 pages monitored 24/7 across 5 tracked websites"]},
                    {"name": "Enterprise", "price": "Custom pricing", "billing": "Annual contract; contact sales for a quote", "features": ["600+ AI writing assistant drafts per year", "2,500+ AI search credits, 125,000+ pages analyzed, 60,000+ tracked keywords, 75+ tracked competitors", "24/7 monitoring for websites of any size across 10+ tracked properties"]},
