      {"name": "Fishbowl Advanced", "price": "Custom quote", "billing": "On-premise license, priced per user", "features": ["On-premise deployment", "Advanced manufacturing tools", "Greater customization"]},
      {"name": "Fishbowl AI Insights", "price": "Custom add-on quote", "billing": "Add-on module, priced separately", "features": ["AI forecasting", "Athena AI assistant", "Trend and risk analysis dashboards"]}
