def slugify(s):
    return re.sub(r"[^a-z0-9]+", "-", s.lower()).strip("-")

ALL_TOOLS = []
for cat in CATEGORIES:
    for t in cat["tools"]:
        t["category"] = cat["name"]
        t["cat_slug"] = cat["slug"]
        t["slug"] = slugify(t["name"])
        ALL_TOOLS.append(t)


