REMOVED_SLUGS = {slugify(_t["name"]) for _t in REMOVED_TOOLS}
PARTNER_SLUGS = {"deepsolv", "groweasy", "talkeasy", "arka-inventory"}
FOUNDER_SLUGS = {"pagelens-ai"}
