# ---------- sitemap.xml ----------

def _sitemap_url(loc, priority="0.7", changefreq="weekly"):
    return f"""  <url>
    <loc>{loc}</loc>
    <changefreq>{changefreq}</changefreq>
    <priority>{priority}</priority>
  </url>"""

_sitemap_entries = [
    _sitemap_url(f"{SITE_URL}/", "1.0", "weekly"),
    _sitemap_url(f"{SITE_URL}/all-tools.html", "0.9", "weekly"),
    _sitemap_url(f"{SITE_URL}/blog/", "0.7", "weekly"),
    _sitemap_url(f"{SITE_URL}/reviews/", "0.8", "weekly"),
    _sitemap_url(f"{SITE_URL}/about.html", "0.5", "monthly"),
    _sitemap_url(f"{SITE_URL}/submit-tool.html", "0.5", "monthly"),
    _sitemap_url(f"{SITE_URL}/compare.html", "0.7", "monthly"),
]
for cat in CATEGORIES:
    _sitemap_entries.append(_sitemap_url(f"{SITE_URL}/categories/{cat['slug']}.html", "0.8", "weekly"))
for t in ALL_TOOLS:
    _sitemap_entries.append(_sitemap_url(f"{SITE_URL}/tools/{t['slug']}.html", "0.9", "weekly"))
for post in BLOG_POSTS:
    _sitemap_entries.append(_sitemap_url(f"{SITE_URL}/blog/{post['slug']}.html", "0.7", "monthly"))
for comp in MULTI_COMPARISONS:
    _sitemap_entries.append(_sitemap_url(f"{SITE_URL}/blog/{comp['slug']}.html", "0.7", "monthly"))
for rev in REVIEWS:
    _sitemap_entries.append(_sitemap_url(f"{SITE_URL}/reviews/{rev['slug']}.html", "0.9", "monthly"))

sitemap_xml = f"""<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
{chr(10).join(_sitemap_entries)}
</urlset>
"""
with open(os.path.join(ROOT, "sitemap.xml"), "w") as f:
    f.write(sitemap_xml)

